        if all(x == seq[0] for x in seq):
            return 0
        else:
            return 1 + find_degree(calculate_differences(seq))

    degree = find_degree(sequence)
    differences = sequence[:]
    for _ in range(degree):
        differences = calculate_differences(differences)

    next_value = sequence[-1] + differences[-1]
    return degree, next_value

def main():
    import sys
    input = sys.stdin.read
    data = input().split()
    n = int(data[0])
    sequence = list(map(int, data[1:]))
    degree, next_value = find_degree_and_next_value(sequence)
    print(degree, next_value)

if __name__ == "__main__":
